                code: "import { createElement } from 'react'\nimport { useStore } from '@migaia/store-react'\nimport { counter } from './counter-store.ts'\nconst readCount = (state: { count: number }) => state.count\nexport function Quantity() {\n  const count = useStore(counter, readCount)\n  const onClick = () => counter.increment()\n  return createElement('button', { onClick }, `数量 ${count}`)\n}"
