                code: "import { createElement } from 'react'\nimport { useStoreConfig, useStoreFeature, useAssertStoreFeature } from '@migaia/store-react'\nexport function Receipt() {\n  const enabled = useStoreFeature('experimental.receipt')\n  const config = useStoreConfig()\n  useAssertStoreFeature('experimental.receipt', 'Receipt')\n  return createElement(\n    'span',\n    null,\n    enabled && config?.defaults.warnAsyncActions ? 'Receipt preview' : 'Basic receipt'\n  )\n}"
