                code: "import { createRuntime } from '@migaia/reactive'\nimport { createAtomStore } from '@migaia/store-keyed'\nimport { drafts } from './draft-definitions.ts'\nconst runtime = createRuntime()\nconst store = createAtomStore(runtime)\nconst draft = drafts('support')\ntry {\n  store.set(draft, (value) => ({ ...value, text: 'Reply saved' }))\n  console.log(store.get(draft).text)\n  const released = store.release(draft)\n  drafts.forget('support')\n  console.log(JSON.stringify({ released, remainingInstances: store.size }))\n} finally {\n  store.dispose()\n  drafts.clear()\n}"
