                code: "import { abort, connect, createEndpoint, createRpcIdempotencyStore } from '@migaia/rpc-core'\nimport { ping, timeout } from '@migaia/rpc-core'\nimport { createMemoryTransportPair } from '@migaia/rpc-core/adapters/memory'\nexport async function openEndpoints() {\n  const [left, right] = createMemoryTransportPair()\n  const server = await createEndpoint({\n    id: 'catalog',\n    transport: right,\n    idempotency: { store: createRpcIdempotencyStore() },\n    middlewares: [connect(), abort(), timeout({ timeoutMs: 1000 }), ping()] as const\n  })\n  const client = await createEndpoint({\n    id: 'checkout',\n    targetIds: ['catalog'],\n    transport: left,\n    middlewares: [connect(), abort(), timeout({ timeoutMs: 1000 }), ping()] as const\n  })\n  return { client, server, transport: left }\n}"
