                code: "import { defineTrayHost } from '@migaia/tray'\nimport { orderPlugin } from './order-plugin.ts'\n\nexport const publisher = defineTrayHost({\n  name: 'publisher',\n  plugins: (_info, trayPlugin) => [orderPlugin(trayPlugin)] as const,\n  exposes: ['orders.events']\n})"
